INSERT INTO studies (id, slug, title, subtitle, study_number, series_id, content_type, access_level, status, summary_markdown, original_publication_date, cover_image_url, total_slides, search_keywords, curator_notes, created_at, updated_at, created_by, updated_by) VALUES ('s_ganesa_001', 'ganesa-variations-in-iconography', 'Ganesa: Variations in Iconography', 'Postural/Compositional, Anatomical, and Regional Distinctive Forms', 'Study 001', 11, 'study', 'public', 'published', 'This handcrafted Panchaloha bronze Ganesha is depicted seated in   lalitasana   on a tiered lotus pedestal. The four-armed form holds   ankusa   and   pasa   in the upper hands, and   danta   and   modaka   in the lower hands. The trunk curves across the body, with broad ears, rounded abdomen and de', '2026-09-11', '/storage/images/ganesa-variations-in-iconography/slide_1.png', 7, 'Objects, Symbols, Asina, Lalitasana, Ganesha, Panchaloha, Modaka, Ankusa', 'Curated from Five Metal Masonry authentic bronze collection', '2026-09-13 12:01:18.771914', '2026-09-13 12:01:18.796506', 'curator', 'curator');
INSERT INTO studies (id, slug, title, subtitle, study_number, series_id, content_type, access_level, status, summary_markdown, original_publication_date, cover_image_url, total_slides, search_keywords, curator_notes, created_at, updated_at, created_by, updated_by) VALUES ('s_nataraja_002', 'nataraja-cosmic-dance-iconometry', 'Nataraja: Cosmic Dance & Classical Iconometry', 'Iconography of the Ananda Tandava and Chola Bronzes', 'Study 002', 11, 'study', 'member_only', 'published', 'Handcrafted panchaloha bronze icon of Naṭarāja from the Masterpieces collection, depicted in the classic ānanda-tāṇḍava within a prabhāmaṇḍala of flaming tongues. The four-armed form presents the ḍamaru and agni in the upper hands, with abhaya and gaja-hasta (karaṇa) articulating the lower gestures.', '2026-09-12', '/storage/images/nataraja-cosmic-dance-iconometry/slide_1.png', 4, 'Nataraja, Shiva, Tandava, Ananda Tandava, Apasmara, Chola, Bronze, Agni, Damaru', 'Premium Monograph reserved for Scholar Pro Members', '2026-09-13 12:01:18.771914', '2026-09-13 12:01:18.796506', 'curator', 'curator');
INSERT INTO studies (id, slug, title, subtitle, study_number, series_id, content_type, access_level, status, summary_markdown, original_publication_date, cover_image_url, total_slides, search_keywords, curator_notes, created_at, updated_at, created_by, updated_by) VALUES ('s_uchchhishta_003', 'uchchhishta-ganapati-tantric-iconography', 'Uchchhishta Ganapati: Tantric Dual-Figure Composition', 'Esoteric Ganapatya Iconography and Devi Manifestation', 'Study 003', 11, 'study', 'public', 'published', 'Handcrafted panchaloha bronze icon of Uchchhishta Ganapati, a tantric form of Ganesha, depicted seated with the Devi on his left lap. The composition presents an intimate dual-figure arrangement, with the four-armed form carrying canonical attributes, and the trunk extending across towards the Devi.', '2026-09-12', '/storage/images/uchchhishta-ganapati-tantric-iconography/slide_1.png', 4, 'Symbols, Tantric, Ganapatya, Devi, Panchaloha, Dual Figure, Lalitasana', 'Public Access', '2026-09-13 12:01:18.771914', '2026-09-13 12:01:18.796506', 'curator', 'curator');
INSERT INTO studies (id, slug, title, subtitle, study_number, series_id, content_type, access_level, status, summary_markdown, original_publication_date, cover_image_url, total_slides, search_keywords, curator_notes, created_at, updated_at, created_by, updated_by) VALUES ('s_kaliya_004', 'kaliya-tandava-krishna-iconometry', 'Kaliya Tandava Krishna: Dynamic Postural Iconometry', 'Serpentine Foot Placement and Equilibrium in Chola-Style Bronzes', 'Study 004', 6, 'study', 'public', 'published', 'Handcrafted Panchaloha bronze of Kaliya Tandava Krishna  , from our Masterpieces Collection  
INSERT INTO studies (id, slug, title, subtitle, study_number, series_id, content_type, access_level, status, summary_markdown, original_publication_date, cover_image_url, total_slides, search_keywords, curator_notes, created_at, updated_at, created_by, updated_by) VALUES ('s_venugopala_005', 'krishna-venugopala-tribhanga-posture', 'Krishna Venugopala: The Tribhanga Posture & Bamboo Flute', 'Three-Bend Canon, Cowherd Attire, and Cadence of the Flute', 'Study 005', 3, 'study', 'member_only', 'published', 'Venugopala, the flute-playing form of Krishna, is depicted standing in   svastikasana  , with one leg gracefully crossed before the other. His hands are raised towards his lips, holding the   venu (flute)   in his characteristic flute-playing gesture.  
INSERT INTO studies (id, slug, title, subtitle, study_number, series_id, content_type, access_level, status, summary_markdown, original_publication_date, cover_image_url, total_slides, search_keywords, curator_notes, created_at, updated_at, created_by, updated_by) VALUES ('s_radhakrishna_006', 'radha-krishna-composite-proportions', 'Radha-Krishna: Composite Divine Proportions', 'Dual-Scale Harmony and Shilpa Shastra Dvandva Rules', 'Study 006', 3, 'study', 'member_only', 'published', 'A handcrafted Panchaloha bronze depiction of   Radha and Krishna  , composed as a paired standing form rooted in the South Indian sculptural tradition.  
INSERT INTO studies (id, slug, title, subtitle, study_number, series_id, content_type, access_level, status, summary_markdown, original_publication_date, cover_image_url, total_slides, search_keywords, curator_notes, created_at, updated_at, created_by, updated_by) VALUES ('s_study_of_rare_va_6d2f', 'study-of-rare-varahi-iconography', 'Study of Rare Varahi Iconography', NULL, NULL, 1, 'study', 'public', 'draft', NULL, NULL, NULL, 0, NULL, NULL, '2026-09-13 06:38:20.246255', '2026-09-13 06:38:20.246255', 'ananth.seetharaman@gmail.com', 'ananth.seetharaman@gmail.com');
INSERT INTO study_slides (id, study_id, slide_number, slide_title, image_url, thumbnail_url, caption, extracted_ocr_text, cleaned_text, visual_elements_summary, sort_order) VALUES ('sl_1', 's_ganesa_001', 1, 'Variations in Iconography: Scope & Methodology', '/storage/images/ganesa-variations-in-iconography/slide_1.png', '/storage/images/ganesa-variations-in-iconography/slide_1.png', 'Introductory scope outlining visible variations in posture, composition, arms, faces, trunk orientation, and regional configurations.', 'ICONOGRAPHY VARIATIONS IN ICONOGRAPHY The iconography of Ganesa presents considerable variation in posture, composition and anatomical form. This study examines these visible variations— including the number of arms and faces, disposition of the trunk and distinctive regional configurations—rather than presenting another prescribed set of forms. Some of these variations occur within the well- known 32 forms of GaQeSa (covered earlier) and are revisited here specifically to -illustrate their distinctive iconographic features. This study considers variations that are visibly rather than expressed in the icon itself, distinctions based solely on epithets, legends or sthala-puräQa traditions. FIVE METAL MASONRY fivemetalmasonry.com', 'The iconography of Gaṇeśa presents considerable variation in posture, composition and anatomical form. This study examines these visible variations—including the number of arms and faces, disposition of the trunk and distinctive regional configurations—rather than presenting another prescribed set of forms. Some of these variations occur within the well-known 32 forms of Gaṇeśa (covered earlier) and are revisited here specifically to illustrate their distinctive iconographic features. This study considers variations that are visibly expressed in the icon itself, rather than distinctions based solely on epithets, legends or sthala-purāṇa traditions.', 'Title parchment with Five Metal Masonry hand emblem logo.', 1);
INSERT INTO study_slides (id, study_id, slide_number, slide_title, image_url, thumbnail_url, caption, extracted_ocr_text, cleaned_text, visual_elements_summary, sort_order) VALUES ('sl_2', 's_ganesa_001', 2, 'Taxonomy of Ganesa Variations: Postural, Anatomical, Regional', '/storage/images/ganesa-variations-in-iconography/slide_2.png', '/storage/images/ganesa-variations-in-iconography/slide_2.png', 'Complete systematic breakdown: Postural & Compositional, Anatomical (Bahu-bheda, Mukha-bheda, Sunda-bheda), Regional forms, and Vahana variations.', 'ICONOGRAPHY QAN ESA VARIATIONS IN ICONOGRAPHY 1. POSTURAL & COMPOSITIONAL VARIATIONS • ÄsTna — seated; several variations in leg disposition occur. • Sthänaka — standing • Nrtta — dancing • Mü$kavähana — mounted/seated upon the mü#ika • With Devi/Devis • Samkara Murtis - ganesa combined with another divinity 2. ANATOMICAL VARIATIONS Bähu-bheda — number of arms • Dvibhuja — two-armed representations • Caturbhuja — four-armed; the most familiar depiction. • Sadbhuja, A#Cabhuja, Dagabhuja and other multi-armed forms Mukha-bheda — number of heads/faces • Ekamukha single-headed, the usual form. • Dvimukha / Trimukha / Paficamukha — clearly established forms Sundä-bheda — orientation of the trunk • Left-turning • Right-turning • Central/descending 3. REGIONAL / DISTINCTIVE FORMS FIVE METAL MASONRY fivemetalmasonry.com • Ädi Vinäyaka, Thilatharpanapuri — human-headed form • TriSuQ4a GaQapati, Pune— three-trunked form • Garh Ganesh, Jaipur - trunkless form VAHANA VARIATION Distinctive vähanas are covered under their respective forms — Heramba Ganapati, the paöcamukha form, with the lion; and TriSutpda Ganapati, with the peacock.', '1. Postural & Compositional Variations: Āsīna (seated), Sthānaka (standing), Nṛtta (dancing), Mūṣikavāhana (mounted upon mūṣika), With Devi/Devis, Saṅkara Mūrtis (combined with another divinity). 2. Anatomical Variations: Bāhu-bheda (arms: Dvibhuja, Caturbhuja, Ṣaḍbhuja, Aṣṭabhuja, Daśabhuja), Mukha-bheda (heads: Ekamukha, Dvimukha, Trimukha, Pañcamukha), Śuṇḍā-bheda (trunk: Left-turning, Right-turning, Central/descending). 3. Regional / Distinctive Forms: Ādi Vināyaka, Thilatharpanapuri (human-headed), Triśuṇḍa Gaṇapati, Pune (three-trunked), Garh Ganesh, Jaipur (trunkless). Vāhana Variation: Heramba Gaṇapati with lion (siṃha); Triśuṇḍa Gaṇapati with peacock (mayūra).', 'Comprehensive classification list on aged parchment background.', 2);
INSERT INTO study_slides (id, study_id, slide_number, slide_title, image_url, thumbnail_url, caption, extracted_ocr_text, cleaned_text, visual_elements_summary, sort_order) VALUES ('sl_3', 's_ganesa_001', 3, 'Comparative Plate: 20 Iconographic Variations of Ganesa', '/storage/images/ganesa-variations-in-iconography/slide_3.png', '/storage/images/ganesa-variations-in-iconography/slide_3.png', 'Illustrated comparative plate demonstrating the 20 visual variations drawn from bronzes, stone sculptures, and classical iconometry.', 'ICONOGRAPHY VARIATIONS IN ICONOGRAPHY POSTURAL/COMPOSITIONAL • ANATOMICAL • REGIONAL POSTURAL & COMPOSITIONAL VARIATIONS ASINA SAD-BHUJA STANA ASTA-BHUJA MUSHIKA VAHANA ANATOMICAL VARIATIONS ASA-BHUJA SODASA-BÅUJA REGIONAL DISTINCTIVE FORMS DEVI SAHITA AMKARA MURTI ATUR-BHUJ DAKSINAVARTL•: FIVE METAL MASONRY fivemetalmasonry.com ADI- TN TRISHUND PANA''fi, PUNE GARH GANAPTI, JAIPUR', 'Visual comparative iconography plate illustrating: Row 1 (Postural): Āsīna, Sthānaka, Nṛtta, Mūṣika Vāhana, Devi Sahita, Saṅkara Mūrtis. Row 2 & 3 (Anatomical): Dvi-mukha, Tri-mukha, Pañca-mukha, Dvi-bhuja, Catur-bhuja, Ṣaḍ-bhuja, Aṣṭa-bhuja, Daśa-bhuja, Ṣoḍaśa-bhuja, Vāmāvarta, Dakṣiṇāvarta. Row 4 (Regional): Ādi-Vināyaka (Tamil Nadu, Human Form), Trishund Ganapati (Pune, Three Trunked), Garh Ganapati (Jaipur, Trunkless).', '20 detailed hand-drawn iconographic line drawings in 4 registers.', 3);
INSERT INTO study_slides (id, study_id, slide_number, slide_title, image_url, thumbnail_url, caption, extracted_ocr_text, cleaned_text, visual_elements_summary, sort_order) VALUES ('sl_4', 's_ganesa_001', 4, 'Postural Variations: Asina | Sitting Postures in Detail', '/storage/images/ganesa-variations-in-iconography/slide_4.png', '/storage/images/ganesa-variations-in-iconography/slide_4.png', 'Deep iconographic reading of seated forms: padmasana, sukhasana, lalitasana, ardhaparyankasana, and bhadrasana.', 'ICONOGRAPHY POSTURAL VARIATIONS ÄSiNA I SITTING In the äsrna form, Ganesa is represented seated in a stable and composed posturer with the legs arranged in several ways according to the specific iconographic form. He in padmäsana (lotus may sit posture), sukhäsana (easy posture), lalitäsana (posture of royal ease), or ardhaparyahkäsana (with one leg — pendant and the other drawn up). He may also be shown in bhadräsana (a formal seated posture, generally with both feet placed on a support or with the legs arranged symmetrically). The characteristic elephant head, large ears and prominent rounded belly are retained, while the number ¯ of arms, gestures and attributes may vary according to the specific iconographic form. FIVE METAL MASONRY fivemetalmasonry.com', 'In the āsīna form, Gaṇeśa is represented seated in a stable and composed posture, with the legs arranged in several ways according to the specific iconographic form. He may sit in padmāsana (lotus posture), sukhāsana (easy posture), lalitāsana (posture of royal ease), or ardhaparyaṅkāsana (with one leg pendant and the other drawn up). He may also be shown in bhadrāsana (a formal seated posture, generally with both feet placed on a support or with the legs arranged symmetrically). The characteristic elephant head, large ears and prominent rounded belly are retained, while the number of arms, gestures and attributes may vary according to the specific iconographic form.', 'Line drawing of Caturbhuja Ganesha seated in Lalitasana on a padmapitha holding pasa and ankusa with modaka on trunk.', 4);
INSERT INTO study_slides (id, study_id, slide_number, slide_title, image_url, thumbnail_url, caption, extracted_ocr_text, cleaned_text, visual_elements_summary, sort_order) VALUES ('sl_nat_1', 's_nataraja_002', 1, 'Plate 1: Canonical Perspective - Nataraja 18" Masterpiece', '/storage/images/nataraja-cosmic-dance-iconometry/slide_1.png', '/storage/images/nataraja-cosmic-dance-iconometry/slide_1.png', 'Handcrafted panchaloha bronze icon of Naṭarāja from the Masterpieces collection, depicted in the classic ānanda-tāṇḍava within a prabhāmaṇḍala of flaming tongues. The four-armed form presents the ḍamaru and agni in the upper hands, with abhaya and gaja-hasta (karaṇa) articulating the lower gestures.', 'Handcrafted panchaloha bronze icon of Naṭarāja from the Masterpieces collection, depicted in the classic ānanda-tāṇḍava within a prabhāmaṇḍala of flaming tongues. The four-armed form presents the ḍamaru and agni in the upper hands, with abhaya and gaja-hasta (karaṇa) articulating the lower gestures.', 'Handcrafted panchaloha bronze icon of Naṭarāja from the Masterpieces collection, depicted in the classic ānanda-tāṇḍava within a prabhāmaṇḍala of flaming tongues. The four-armed form presents the ḍamaru and agni in the upper hands, with abhaya and gaja-hasta (karaṇa) articulating the lower gestures.', 'Plate 1: Canonical Perspective - Nataraja 18" Masterpiece', 1);
