INSERT INTO study_slides (id, study_id, slide_number, slide_title, image_url, thumbnail_url, caption, extracted_ocr_text, cleaned_text, visual_elements_summary, sort_order) VALUES ('sl_8b18a50ad6b8', 's_ganesa_001', 5, 'Curated Slide: New Iconography Plate', '/storage/images/ganesa-variations-in-iconography/upload_d34ce8_WhatsApp Image 2026-09-11 at 7.29.36 AM.jpeg', '/storage/images/ganesa-variations-in-iconography/upload_d34ce8_WhatsApp Image 2026-09-11 at 7.29.36 AM.jpeg', 'Curated slide 5', 'ICONOGRAPHY POSTURAL VARIATIONS ÄSiNA I SITTING In the äsrna form, Ganesa is represented seated in a stable and composed posturer with the legs arranged in several ways according to the specific iconographic form. He in padmäsana (lotus may sit posture), sukhäsana (easy posture), lalitäsana (posture of royal ease), or ardhaparyahkäsana (with one leg — pendant and the other drawn up). He may also be shown in bhadräsana (a formal seated posture, generally with both feet placed on a support or with the legs arranged symmetrically). The characteristic elephant head, large ears and prominent rounded belly are retained, while the number ¯ of arms, gestures and attributes may vary according to the specific iconographic form. FIVE METAL MASONRY fivemetalmasonry.com', 'ICONOGRAPHY POSTURAL VARIATIONS ĀSĪNA I SITTING In the āsīna form, Ganesa is represented seated in a stable and composed posturer with the legs arranged in several ways according to the specific iconographic form. He in padmāsana (lotus may sit posture), sukhāsana (easy posture), lalitāsana (posture of royal ease), or ardhaparyaṅkāsana (with one leg — pendant and the other drawn up). He may also be shown in bhadrāsana (a formal seated posture, generally with both feet placed on a support or with the legs arranged symmetrically). The characteristic elephant head, large ears and prominent rounded belly are retained, while the number ¯ of arms, gestures and attributes may vary according to the specific iconographic form. FIVE METAL MASONRY fivemetalmasonry.com', 'High-resolution iconography plate', 5);
INSERT INTO study_slides (id, study_id, slide_number, slide_title, image_url, thumbnail_url, caption, extracted_ocr_text, cleaned_text, visual_elements_summary, sort_order) VALUES ('sl_cc51fdf0d4d3', 's_ganesa_001', 6, 'Shikhara Mudra: Canonical Iconographic Hand Gesture', '/storage/images/ganesa-variations-in-iconography/upload_c3b616_mudra.jfif', '/storage/images/ganesa-variations-in-iconography/upload_c3b616_mudra.jfif', 'Curated slide 5', 'Sikhara literally moans upright ihumb rising above fist hand its characteristic ICONOGRAPHY • Intent: Strength, steadiness, and resolve • Hand: Usually either hand • Position: All fingers fblded firmly into the palm; thumb extended upright Finger flexion: Firm flexion with the thumb held erect and controlled • Emotional tone: Confident, composed, and resolute • Common with: Deities holding bow (Rama, Forms of Siva, Devis), expressiVe iconographic gestures, and ritual hand formations five met a m', 'Shikhara Mudra (Śikhara Hasta) • Upright thumb rising above fist hand • ICONOGRAPHY • Intent: Strength, steadiness, and resolve • Hand: Usually either hand • Position: All fingers folded firmly into the palm; thumb extended upright • Finger flexion: Firm flexion with the thumb held erect and controlled • Emotional tone: Confident, composed, and resolute • Common with: Deities holding bow (Rama, Forms of Siva, Devis), expressive iconographic gestures, and ritual hand formations in Panchaloha bronze casting.', 'High-resolution iconography plate', 6);
INSERT INTO study_slides (id, study_id, slide_number, slide_title, image_url, thumbnail_url, caption, extracted_ocr_text, cleaned_text, visual_elements_summary, sort_order) VALUES ('sl_09b140bc6fdb', 's_ganesa_001', 6, 'Shikhara Mudra: Canonical Iconographic Hand Gesture', '/storage/images/ganesa-variations-in-iconography/upload_c3b616_mudra.jfif', '/storage/images/ganesa-variations-in-iconography/upload_c3b616_mudra.jfif', 'Curated slide 6', 'Sikhara literally moans upright ihumb rising above fist hand its characteristic ICONOGRAPHY', 'Śikhara (Mudra / Hasta): Literally denotes upright thumb rising above fist hand.', 'High-resolution iconography plate', 6);
