INSERT INTO dictionary_entries (id, slug, headword, iast_headword, part_of_speech, etymology, definition, extended_notes, created_at, updated_at, created_by, updated_by) VALUES ('d1', 'asina', 'Asina', 'Āsīna', 'participle / adjective', 'From Sanskrit root ās (to sit, rest)', 'Seated posture; a generic term for any iconographic form depicted in a sitting position.', 'Contrasts with sthānaka (standing) and nṛtta (dancing). Includes padmāsana, sukhāsana, lalitāsana, ardhaparyaṅkāsana, and bhadrāsana.', '2026-09-13 12:01:18.838984', '2026-09-13 12:01:18.848210', 'curator', 'curator');
INSERT INTO dictionary_entries (id, slug, headword, iast_headword, part_of_speech, etymology, definition, extended_notes, created_at, updated_at, created_by, updated_by) VALUES ('d2', 'lalitasana', 'Lalitasana', 'Lalitāsana', 'noun, neuter', 'From Sanskrit lalita (charming, graceful) + āsana', 'The posture of royal ease, wherein one leg is folded on seat while the other hangs down gracefully.', 'Quintessential posture for benevolent divinities including Ganesha and Devi.', '2026-09-13 12:01:18.838984', '2026-09-13 12:01:18.848210', 'curator', 'curator');
INSERT INTO dictionary_entries (id, slug, headword, iast_headword, part_of_speech, etymology, definition, extended_notes, created_at, updated_at, created_by, updated_by) VALUES ('d3', 'sukhasana', 'Sukhasana', 'Sukhāsana', 'noun, neuter', 'From sukha (comfort) + āsana', 'Comfortable seated posture; relaxed informal disposition of legs.', 'Observed in Siva Somaskanda bronzes.', '2026-09-13 12:01:18.838984', '2026-09-13 12:01:18.848210', 'curator', 'curator');
INSERT INTO dictionary_entries (id, slug, headword, iast_headword, part_of_speech, etymology, definition, extended_notes, created_at, updated_at, created_by, updated_by) VALUES ('d4', 'ardhaparyankasana', 'Ardhaparyankasana', 'Ardhaparyaṅkāsana', 'noun, neuter', 'From ardha + paryaṅka + āsana', 'Seated posture with one leg folded and one knee elevated with pendant foot.', 'Frequently used in Agamic descriptions of meditative royalty.', '2026-09-13 12:01:18.838984', '2026-09-13 12:01:18.848210', 'curator', 'curator');
INSERT INTO dictionary_entries (id, slug, headword, iast_headword, part_of_speech, etymology, definition, extended_notes, created_at, updated_at, created_by, updated_by) VALUES ('d5', 'bhadrasana', 'Bhadrasana', 'Bhadrāsana', 'noun, neuter', 'From bhadra (auspicious) + āsana', 'Majestic sitting posture where feet rest on a support or soles meet symmetrically.', 'Classical imperial seated posture in Shilpa Shastras.', '2026-09-13 12:01:18.838984', '2026-09-13 12:01:18.848210', 'curator', 'curator');
INSERT INTO dictionary_entries (id, slug, headword, iast_headword, part_of_speech, etymology, definition, extended_notes, created_at, updated_at, created_by, updated_by) VALUES ('d6', 'trishunda', 'Trishunda', 'Triśuṇḍa', 'adjective / noun', 'From tri (three) + śuṇḍā (trunk)', 'Possessing three elephant trunks; rare iconographic manifestation.', 'Exemplified in Pune Trishund temple.', '2026-09-13 12:01:18.838984', '2026-09-13 12:01:18.848210', 'curator', 'curator');
INSERT INTO doc_ref_catalog (doc_ref, doc_name, corpus, section, author_or_tradition, language, applicability_to_iconography, created_at, updated_at, created_by, updated_by) VALUES ('DOC_REF_001', 'Mānasāra Śilpa Śāstra', 'Agama & Vastu Shastra Corpus', 'Chapter 51-56: Tālamāna & Pratima Lakshana', 'Maharshi Mānasāra', 'Sanskrit (IAST)', 'Foundational text for iconometric proportions (Navatala, Dasatala) and divine bronze casting.', '2026-09-13 12:01:55.732930', '2026-09-13 12:01:55.732930', 'system', 'system');
INSERT INTO doc_ref_catalog (doc_ref, doc_name, corpus, section, author_or_tradition, language, applicability_to_iconography, created_at, updated_at, created_by, updated_by) VALUES ('DOC_REF_002', 'Śilparatna', 'South Indian Silpa Corpus', 'Part II: Iconography of Devas & Devis', 'Śrīkumāra of Kerala (16th C CE)', 'Sanskrit', 'Detailed treatises on mudras, ayudhas, postures, and Panchaloha alloy mixing formulas.', '2026-09-13 12:01:55.799086', '2026-09-13 12:01:55.799086', 'system', 'system');
INSERT INTO doc_ref_catalog (doc_ref, doc_name, corpus, section, author_or_tradition, language, applicability_to_iconography, created_at, updated_at, created_by, updated_by) VALUES ('DOC_REF_003', 'Kāraṇāgama', 'Saiva Agamic Corpus', 'Kriya Pada: Murti Laksana', 'Saiva Siddhanta Tradition', 'Sanskrit (Grantha Script)', 'Prescribes ritual dimensions, postures, and iconographic marks for Siva, Ganesha, and Skanda.', '2026-09-13 12:01:55.869151', '2026-09-13 12:01:55.869151', 'system', 'system');
INSERT INTO doc_ref_catalog (doc_ref, doc_name, corpus, section, author_or_tradition, language, applicability_to_iconography, created_at, updated_at, created_by, updated_by) VALUES ('DOC_REF_004', 'Mayamata', 'Vastu & Silpa Shastra Corpus', 'Chapters 34-36: Sculptural Proportions', 'Mayamuni', 'Sanskrit', 'Comprehensive manual on architectural sculpture, bronze casting, and iconographic symmetry.', '2026-09-13 12:01:55.937201', '2026-09-13 12:01:55.937201', 'system', 'system');
INSERT INTO doc_ref_catalog (doc_ref, doc_name, corpus, section, author_or_tradition, language, applicability_to_iconography, created_at, updated_at, created_by, updated_by) VALUES ('DOC_REF_005', 'Elements of Hindu Iconography', 'Modern Epigraphical Corpus', 'Volumes I & II', 'T.A. Gopinatha Rao (1914)', 'English / Sanskrit Citations', 'Pioneering academic baseline reference cross-referencing Agamic texts with Chola/Pallava bronzes.', '2026-09-13 12:01:56.009609', '2026-09-13 12:01:56.009609', 'system', 'system');
INSERT INTO places (id, slug, name, native_name, temple_name, deity_enshrined, tradition, town_city, district, state, country, notes) VALUES ('p1', 'adi-vinayaka-thilatharpanapuri', 'Adi Vinayaka Temple, Thilatharpanapuri', 'ஆதி விநாயகர்', 'Muktheeswarar Temple complex', 'Nara-mukha Ganesha', 'Saiva / Ganapatya', 'Thilatharpanapuri', 'Tiruvarur', 'Tamil Nadu', 'India', 'Human-faced Ganesha without elephant head.');
INSERT INTO places (id, slug, name, native_name, temple_name, deity_enshrined, tradition, town_city, district, state, country, notes) VALUES ('p2', 'trishund-ganapati-pune', 'Trishund Mayureshwar Ganapati, Pune', 'त्रिशुंड गणपती', 'Trishund Ganapati Temple', 'Three-trunked Ganesha on peacock', 'Ganapatya', 'Pune', 'Pune', 'Maharashtra', 'India', '18th-century temple in Somwar Peth featuring 3 trunks on peacock mount.');
