INSERT INTO slide_ocr_data (id, slide_id, ocr_engine, language_tag, raw_ocr_output, normalized_text, word_count, confidence_avg, tokens_json) VALUES ('ocr_sl_8b18a50ad6b8', 'sl_8b18a50ad6b8', 'windows_media_ocr', 'en-US', 'ICONOGRAPHY POSTURAL VARIATIONS ÄSiNA I SITTING In the äsrna form, Ganesa is represented seated in a stable and composed posturer with the legs arranged in several ways according to the specific iconographic form. He in padmäsana (lotus may sit posture), sukhäsana (easy posture), lalitäsana (posture of royal ease), or ardhaparyahkäsana (with one leg — pendant and the other drawn up). He may also be shown in bhadräsana (a formal seated posture, generally with both feet placed on a support or with the legs arranged symmetrically). The characteristic elephant head, large ears and prominent rounded belly are retained, while the number ¯ of arms, gestures and attributes may vary according to the specific iconographic form. FIVE METAL MASONRY fivemetalmasonry.com', 'ICONOGRAPHY POSTURAL VARIATIONS ĀSĪNA I SITTING In the āsīna form, Ganesa is represented seated in a stable and composed posturer with the legs arranged in several ways according to the specific iconographic form. He in padmāsana (lotus may sit posture), sukhāsana (easy posture), lalitāsana (posture of royal ease), or ardhaparyaṅkāsana (with one leg — pendant and the other drawn up). He may also be shown in bhadrāsana (a formal seated posture, generally with both feet placed on a support or with the legs arranged symmetrically). The characteristic elephant head, large ears and prominent rounded belly are retained, while the number ¯ of arms, gestures and attributes may vary according to the specific iconographic form. FIVE METAL MASONRY fivemetalmasonry.com', 118, 0.96, '{}');
INSERT INTO slide_ocr_data (id, slide_id, ocr_engine, language_tag, raw_ocr_output, normalized_text, word_count, confidence_avg, tokens_json) VALUES ('ocr_sl_cc51fdf0d4d3', 'sl_cc51fdf0d4d3', 'windows_media_ocr', 'en-US', 'Sikhara literally moans upright ihumb rising above fist hand its characteristic ICONOGRAPHY • Intent: Strength, steadiness, and resolve • Hand: Usually either hand • Position: All fingers fblded firmly into the palm; thumb extended upright Finger flexion: Firm flexion with the thumb held erect and controlled • Emotional tone: Confident, composed, and resolute • Common with: Deities holding bow (Rama, Forms of Siva, Devis), expressiVe iconographic gestures, and ritual hand formations five met a m', 'Sikhara literally moans upright ihumb rising above fist hand its characteristic ICONOGRAPHY • Intent: Strength, steadiness, and resolve • Hand: Usually either hand • Position: All fingers fblded firmly into the palm; thumb extended upright Finger flexion: Firm flexion with the thumb held erect and controlled • Emotional tone: Confident, composed, and resolute • Common with: Deities holding bow (Rama, Forms of Siva, Devis), expressiVe iconographic gestures, and ritual hand formations five met a m', 75, 0.96, '{}');
INSERT INTO slide_ocr_data (id, slide_id, ocr_engine, language_tag, raw_ocr_output, normalized_text, word_count, confidence_avg, tokens_json) VALUES ('ocr_sl_09b140bc6fdb', 'sl_09b140bc6fdb', 'windows_media_ocr', 'en-US', 'Sikhara literally moans upright ihumb rising above fist hand its characteristic ICONOGRAPHY', 'Śikhara (Mudra / Hasta): Literally denotes upright thumb rising above fist hand.', 12, 0.96, '{}');
